<script setup lang="ts">
import {computed} from 'vue';
import type {Command,PublicView,Position} from '../core/types';
import type {Locale} from '../ui/i18n';
import {alphaText,type AlphaKey} from './i18n';
const props=defineProps<{view:PublicView;locale:Locale;disabled:boolean}>();
const emit=defineEmits<{command:[value:Command]}>();
const t=(key:AlphaKey)=>alphaText(props.locale,key);
const near=(p:Position)=>p.floor===props.view.player.floor&&Math.abs(p.x-props.view.player.x)<=1;
const doors=computed(()=>props.view.alpha!.doors.filter(near)),levers=computed(()=>props.view.alpha!.levers.filter(l=>!l.used&&near(l))),caches=computed(()=>props.view.alpha!.caches.filter(c=>!c.used&&near(c)));
</script>
<template><section class="card map-card"><h2>{{t('minimap')}}</h2><svg viewBox="0 0 280 116" role="img" :aria-label="t('minimap')"><g v-for="(row,floor) in view.explored" :key="floor"><text x="2" :y="12+floor*18" fill="#abbfbc" font-size="9">{{floor+1}}</text><rect v-for="x in row" :key="x" :x="18+x*10" :y="5+floor*18" width="9" height="7" :fill="floor===view.player.floor?'#849b9c':'#465d65'" /></g><line v-for="(l,i) in view.map.ladders" :key="i" :x1="22+l.x*10" :x2="22+l.x*10" :y1="8+l.floor*18" :y2="26+l.floor*18" stroke="#dec48d" stroke-width="2"/><rect v-for="d in view.alpha!.doors" :key="d.id" :x="19+d.x*10" :y="3+d.floor*18" width="6" height="12" :fill="d.open?'#69b49a':d.locked?'#e2946d':'#dec48d'"/><circle :cx="22+view.player.x*10" :cy="8+view.player.floor*18" r="4" fill="#fff4cb"/></svg><small>{{t('mapLegend')}}</small></section>
<section class="card mechanisms"><h2>{{t('mechanisms')}}</h2><p v-if="!doors.length&&!levers.length&&!caches.length">{{t('nothingHere')}}</p><div v-for="door in doors" :key="`d${door.id}`"><p v-if="door.locked">{{t('lockedDoor')}}</p><button v-else :data-door="door.id" :disabled="disabled||view.player.x===door.x" @click="emit('command',`door:${door.id}`)">{{t(door.open?'closeDoor':'openDoor')}}</button></div><button v-for="lever in levers" :key="`l${lever.id}`" :data-lever="lever.id" :disabled="disabled" @click="emit('command',`lever:${lever.id}`)">{{t('lever')}}</button><div v-for="cache in caches" :key="`c${cache.id}`" :data-cache="cache.id"><b>{{t('cache')}}</b><p>{{t('cacheHint')}}</p><div class="cache-actions"><button data-choice="pay" :disabled="disabled||view.player.gold<12" @click="emit('command',`cache:${cache.id}:pay`)">{{t('payCache')}}</button><button data-choice="force" :disabled="disabled||view.player.hp<=8" @click="emit('command',`cache:${cache.id}:force`)">{{t('forceCache')}}</button></div></div></section></template>
<style scoped>.map-card svg{width:100%;display:block}.mechanisms button{font-size:12px;min-height:36px;padding:7px 9px;margin:4px 0}.mechanisms b{font-size:13px}.cache-actions{display:flex;gap:5px;flex-wrap:wrap}.mechanisms>div+div{border-top:1px solid #33474a;padding-top:8px;margin-top:8px}@media(max-width:720px){.map-card,.mechanisms{grid-column:1/-1}}</style>
